 */
function calculateRoots(a, b, c) {
  // coefficient of x^2
  const D = b * b - 4 * a * c;
  if (D < 0) return null;
  if (D === 0) return [-b / (2 * a)];
  return [(-b + Math.sqrt(D)) / (2 * a), (-b - Math.sqrt(D)) / (2 * a)];
